var n=`0468-cig-kofte`;var t=`world-0468`;var o=`TR`;var r=`western-asia`;var s=4;var a=45;var g={en:`Çiğ Köfte`,ua:`Чій кефте`};var l={en:`A traditional dish from Türkiye, centered on red lentils, bulgur, tomato paste, green onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: червона сочевиця, булгур, томатна паста, зелена цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 18 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 18 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:18,i:[[`red-lentils`,250,`g`],[`water`,550,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`bulgur`,220,`g`],[`tomato-paste`,70,`g`],[`hot-paprika`,6,`g`],[`ground-cumin`,4,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Knead the cooked lentil and bulgur mixture until cohesive, form small hand-squeezed oval portions and garnish with fresh greens. No raw meat is used.`,ua:`Ретельно вимісіть приготовлену суміш сочевиці й булгуру до липкості, сформуйте довгасті порції стисканням долоні та додайте свіжу зелень. Сирого м’яса немає.`,t:[`pre-shaping-dough`,`final-proofing`],m:14,i:[[`green-onion`,100,`g`],[`parsley`,50,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lettuce`,180,`g`],[`lemon`,2,`pcs`]]}];var u={slug:n,id:t,country:`TR`,region:r,servings:4,minutes:45,title:g,text:l,steps:d};export{o as country,u as default,t as id,a as minutes,r as region,s as servings,n as slug,d as steps,l as text,g as title};